@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:wght@500;600;700&display=swap');
:root{color-scheme:dark;--ink:#f7f1f5;--muted:#a89cad;--pink:#e6a8c0;--gold:#edcda2;--panel:#211b2b;--line:rgba(255,255,255,.09)}*{box-sizing:border-box}body{margin:0;min-height:100vh;background:radial-gradient(ellipse at 50% -20%,#44314f 0,#211b2a 45%,#15121c 100%);color:var(--ink);font-family:'DM Sans',sans-serif}.game-shell{max-width:1120px;margin:auto;padding:0 40px 22px}.topbar{height:74px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);position:relative;z-index:3}.wordmark{font-size:13px;font-weight:600;letter-spacing:2px;color:#f5eaf2;text-decoration:none}.wordmark b{color:#d5b9da;font-weight:400}.brand-mark{color:var(--gold);font-size:17px;margin-right:8px}.chapter-label{font-size:9px;letter-spacing:1.55px;color:#c5b7ca}.live-dot{display:inline-block;width:6px;height:6px;border-radius:50%;background:#c9a6cf;box-shadow:0 0 10px #d8aada;margin:0 8px 1px 0}.chapter-divider{color:#735f7d;padding:0 9px}.icon-button{width:33px;height:33px;color:#dfc4da;background:#ffffff09;border:1px solid #ffffff16;border-radius:50%;font-size:15px;cursor:pointer}.icon-button:hover,.icon-button.active{background:#e2a8c022;border-color:#e2a8c066}.stage{height:434px;position:relative;overflow:hidden;border:1px solid #ffffff13;border-top:0;border-radius:0 0 8px 8px;background:linear-gradient(180deg,#30253e 0%,#51405b 55%,#7b6178 100%);box-shadow:0 25px 60px #08070d55;isolation:isolate}.stage:before{content:"";position:absolute;inset:auto 0 0;height:112px;background:linear-gradient(180deg,#503e5966,#2b2332);z-index:-1}.scene-glow{position:absolute;width:420px;height:280px;background:#d9a8d52c;filter:blur(60px);left:48%;top:10%;border-radius:50%;z-index:-1}.moon{position:absolute;border-radius:50%;background:#f9e3bc;box-shadow:0 0 38px #f4d7b688;top:42px;left:71%;width:48px;height:48px;opacity:.85}.moon-two{width:47px;height:47px;left:calc(71% + 13px);top:35px;background:#30253e;box-shadow:none}.window-frame{position:absolute;left:61%;top:32px;width:220px;height:176px;border:7px solid #40334a;border-radius:2px 2px 38px 38px;background:#30253e;box-shadow:0 0 0 2px #78637c;overflow:hidden}.window-sky{position:absolute;inset:0;background:linear-gradient(145deg,#28304b,#58466a 70%,#86627d)}.window-cross{position:absolute;inset:0;background:linear-gradient(90deg,transparent 48%,#44364f 48%,#44364f 52%,transparent 52%),linear-gradient(180deg,transparent 50%,#44364f 50%,#44364f 54%,transparent 54%);opacity:.85}.star{position:absolute;color:#ffebc9}.s1{top:18px;left:26px;font-size:12px}.s2{top:50px;left:83px;font-size:22px}.s3{top:30px;right:25px;font-size:15px}.s4{bottom:42px;left:64px;font-size:19px}.s5{bottom:22px;right:28px;font-size:10px}.window-moon{position:absolute;top:23px;right:44px;width:25px;height:25px;background:#f8dfb4;border-radius:50%;box-shadow:0 0 25px #ffe2bd99}.curtain{position:absolute;top:-8px;height:209px;width:61px;background:linear-gradient(90deg,#6a4c67,#a07887 40%,#70546c);z-index:1;filter:drop-shadow(3px 4px 6px #211a2d66)}.curtain-left{left:calc(61% - 13px);clip-path:polygon(0 0,100% 0,82% 100%,32% 100%)}.curtain-right{left:calc(61% + 212px);width:50px;clip-path:polygon(0 0,100% 0,85% 100%,20% 100%)}.bed-back{position:absolute;bottom:15px;left:19%;width:67%;height:164px;background:linear-gradient(180deg,#77637f,#53445f);border-radius:88px 88px 0 0;box-shadow:inset 0 10px #b28fae55;z-index:0}.bed{position:absolute;z-index:1;bottom:-38px;left:14%;width:76%;height:135px;border-radius:55% 48% 0 0/30% 36% 0 0;background:linear-gradient(180deg,#e1c4d2,#b48ba6 65%,#8e6e8b);box-shadow:0 -8px 22px #32253855}.blanket{position:absolute;right:2%;top:10px;width:51%;height:90px;border-radius:55% 48% 5px 25px;background:linear-gradient(165deg,#c8afc7,#917b9e);transform:rotate(-4deg);box-shadow:inset 0 6px #ead4e133}.blanket-fold{position:absolute;left:5%;top:29px;width:32%;height:58px;border-radius:50%;background:#d8bfd0;transform:rotate(5deg)}.pillow{position:absolute;z-index:1;bottom:124px;width:170px;height:68px;border-radius:45%;background:linear-gradient(150deg,#ebd6de,#b9a2c0);box-shadow:inset 0 -7px 8px #705c7750}.pillow-a{left:29%;transform:rotate(8deg)}.pillow-b{left:53%;transform:rotate(-9deg);background:linear-gradient(145deg,#d9c3d9,#a590b1)}.character-wrap{position:absolute;z-index:2;bottom:33px;left:50%;width:min(55vw,560px);height:380px;transform:translateX(-48%);filter:drop-shadow(0 14px 14px #2c20304d);transform-origin:center bottom;transition:filter .4s}.character-art{width:100%;height:100%;overflow:visible}.character-wrap.happy{filter:drop-shadow(0 0 20px #f5b5d255)}.scene-caption{position:absolute;left:24px;bottom:20px;z-index:3;font-size:8px;letter-spacing:1.5px;color:#f4e3e7d9;display:flex;align-items:center;gap:8px}.caption-star{color:#f3d9b7}.caption-line{width:29px;height:1px;background:#efced277}.floating-heart{position:absolute;z-index:5;left:63%;top:39%;color:#ffc7d9;font-size:27px;opacity:0;transform:translateY(12px) scale(.5);pointer-events:none;text-shadow:0 0 18px #ffa4c3}.floating-heart.pop{animation:heart .9s ease-out}@keyframes heart{0%{opacity:0;transform:translateY(12px) scale(.5)}30%{opacity:1;transform:translateY(-8px) scale(1.15)}100%{opacity:0;transform:translateY(-38px) scale(.8)}}.plant{position:absolute;bottom:32px;left:8%;width:55px;height:118px;z-index:1}.plant span{position:absolute;bottom:0;left:14px;width:32px;height:30px;background:linear-gradient(90deg,#8b5364,#c27b83);border-radius:2px 2px 11px 11px}.plant i{position:absolute;bottom:23px;left:28px;width:18px;height:65px;background:#435b55;border-radius:100% 0 100% 0;transform-origin:bottom;transform:rotate(-28deg)}.plant i:nth-child(2){transform:rotate(22deg);height:74px;left:30px}.plant i:nth-child(3){transform:rotate(-55deg);height:52px;left:15px}.plant i:nth-child(4){transform:rotate(53deg);height:54px;left:34px}.plant i:nth-child(5){transform:rotate(4deg);height:85px;left:27px}.bedside{position:absolute;bottom:44px;right:8%;width:106px;height:160px;z-index:0}.nightstand{position:absolute;bottom:0;right:0;width:95px;height:75px;border-radius:4px;background:linear-gradient(90deg,#5b4257,#806071);box-shadow:inset 0 8px #a77a8566}.drawer{position:absolute;top:17px;left:10px;width:75px;height:23px;border:1px solid #c09aa455;border-radius:2px}.drawer-handle{position:absolute;top:27px;left:43px;width:9px;height:3px;border-radius:5px;background:#d9b9ae}.lamp{position:absolute;top:0;left:30px;width:48px;height:73px;background:radial-gradient(ellipse at center,#ffe7bd22,transparent 70%)}.lamp:before{content:"";position:absolute;top:0;left:5px;width:38px;height:34px;border-radius:21px 21px 7px 7px;background:linear-gradient(120deg,#f4d9b6,#c39bab);box-shadow:0 0 23px #f8d8b866}.lamp:after{content:"";position:absolute;left:21px;top:31px;width:7px;height:34px;background:#d0aa9f;clip-path:polygon(35% 0,65% 0,100% 100%,0 100%)}.conversation{position:relative;margin:0 auto;width:min(100%,850px);padding:24px 28px 17px;background:linear-gradient(145deg,#282130,#211b29);border:1px solid #ffffff12;border-radius:0 0 9px 9px;box-shadow:0 17px 45px #09070d49}.conversation-top{display:flex;align-items:center;justify-content:space-between;gap:24px}.speaker{display:flex;align-items:center;gap:11px}.avatar{width:37px;height:37px;border-radius:50%;display:grid;place-items:center;color:#f6dce7;font-family:'Playfair Display',serif;font-size:19px;background:linear-gradient(145deg,#a17c9e,#554361);border:1px solid #edc2d644;box-shadow:0 0 0 3px #ffffff08}.speaker-name{font-family:'Playfair Display',serif;font-size:16px;letter-spacing:.2px}.age-tag{font:9px 'DM Sans',sans-serif;color:#c1a9c5;border:1px solid #a68eaa55;border-radius:8px;padding:2px 6px;vertical-align:2px;margin-left:4px}.speaker-mood{font-size:10px;color:#a89cad;margin-top:3px}.affection{width:215px}.affection-head{display:flex;align-items:center;justify-content:space-between;color:#c9b8cb;font-size:8px;letter-spacing:1.15px}.affection-head strong{font-size:12px;letter-spacing:0;color:#f1d2df}.affection-head small{font-size:9px;font-weight:400;color:#98889e}.meter{height:5px;background:#ffffff13;border-radius:9px;margin-top:7px;position:relative;overflow:hidden}.meter-fill{height:100%;width:0;background:linear-gradient(90deg,#bb86b7,#edacc6,#f3d1bd);border-radius:9px;transition:width .6s cubic-bezier(.2,.8,.2,1)}.meter-glint{position:absolute;right:2px;top:1px;width:2px;height:3px;border-radius:50%;background:#fff;opacity:.7}.affection-note{font-size:8px;color:#9e8ea3;text-align:right;margin-top:5px}.dialogue-row{display:flex;gap:12px;align-items:flex-start;margin:22px 0 19px}.quote-mark{font:34px 'Playfair Display',serif;color:#d9a9c2;line-height:30px;opacity:.8}.dialogue{font:16px/1.55 'Playfair Display',serif;color:#f2e7ec;margin:0;min-height:25px;transition:opacity .2s}.choice-heading{display:flex;justify-content:space-between;align-items:center;font-size:8px;letter-spacing:1.2px;color:#b8a7bc;margin-bottom:9px}.soft-hint{letter-spacing:.1px;font-size:9px;text-transform:none;color:#8f8095}.soft-hint span{color:#e5b4c8;padding-left:4px}.choices{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.choice{position:relative;min-height:48px;text-align:left;padding:9px 28px 9px 12px;color:#e8dce7;background:#ffffff06;border:1px solid #ffffff12;border-radius:5px;font:11px/1.4 'DM Sans',sans-serif;cursor:pointer;transition:background .2s,border .2s,transform .2s}.choice:hover:not(:disabled){background:#d69db51a;border-color:#d6a4bf66;transform:translateY(-2px)}.choice:focus-visible,.restart:focus-visible,.icon-button:focus-visible{outline:2px solid #f1c1d6;outline-offset:3px}.choice:disabled{opacity:.58;cursor:default}.choice .arrow{position:absolute;right:11px;top:50%;transform:translateY(-50%);color:#c99bb9;font-size:15px}.choice .tone{display:block;color:#a994ae;font-size:8px;letter-spacing:.2px;margin-top:2px}.footer-row{display:flex;align-items:center;justify-content:space-between;margin-top:16px}.autosave{font-size:8px;color:#908596}.save-check{display:inline-grid;place-items:center;color:#b8d2b4;border:1px solid #b8d2b455;border-radius:50%;width:12px;height:12px;font-size:8px;margin-right:5px}.restart{font-size:8px;letter-spacing:1px;color:#b3a3b8;background:transparent;border:0;cursor:pointer;padding:5px}.restart span{font-size:14px;color:#e0b0c5;margin-left:4px}.site-note{text-align:center;color:#8f8295;font-size:9px;margin:17px auto 0}.site-note span{color:#b6a4bb;margin-left:7px}.toast{position:fixed;left:50%;bottom:22px;z-index:10;transform:translate(-50%,20px);opacity:0;padding:10px 16px;border:1px solid #ffffff20;background:#2c2333;border-radius:24px;color:#f3dbe6;font-size:11px;box-shadow:0 8px 30px #0005;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(min-width:1200px){.stage{height:460px}.character-wrap{height:400px;width:590px}.conversation{padding-left:34px;padding-right:34px}}
@media(max-width:700px){.game-shell{padding:0 14px 16px}.topbar{height:61px}.wordmark{font-size:11px;letter-spacing:1.5px}.chapter-label{font-size:7px;letter-spacing:.8px}.chapter-divider{padding:0 4px}.stage{height:365px}.window-frame{left:54%;top:26px;width:175px;height:147px}.curtain-left{left:calc(54% - 10px);height:178px}.curtain-right{left:calc(54% + 168px);height:178px}.bed-back{left:9%;width:88%;height:144px}.bed{left:3%;width:96%;height:108px;bottom:-30px}.pillow{bottom:90px;width:130px;height:52px}.pillow-a{left:22%}.pillow-b{left:51%}.character-wrap{width:min(86vw,440px);height:305px;bottom:18px;left:50%}.scene-caption{left:13px;bottom:12px;font-size:7px}.plant{left:1%;transform:scale(.75);transform-origin:bottom left;bottom:20px}.bedside{right:1%;transform:scale(.78);transform-origin:bottom right;bottom:24px}.conversation{padding:18px 16px 13px}.conversation-top{gap:12px}.avatar{width:33px;height:33px}.speaker-name{font-size:15px}.speaker-mood{font-size:9px;max-width:145px}.affection{width:140px}.affection-head{font-size:7px;letter-spacing:.6px}.dialogue-row{margin:17px 0 16px}.dialogue{font-size:15px}.choices{grid-template-columns:1fr;gap:6px}.choice{min-height:43px;padding:8px 32px 8px 11px}.choice .tone{display:inline;margin-left:5px}.footer-row{margin-top:12px}.site-note{font-size:8px;line-height:1.5;padding:0 12px}.soft-hint{font-size:8px}}
@media(max-width:370px){.chapter-label{letter-spacing:.35px}.icon-button{width:29px;height:29px}.affection{width:124px}.speaker-mood{max-width:128px}.stage{height:340px}.character-wrap{height:280px}.choice-heading{font-size:7px}}

(() => {
  const rounds = [
    {
      question: "I was hoping you'd stay a little longer. What would you like to talk about?",
      mood: "a little sleepy, very glad you're here",
      options: [
        { text: "Ask what made her smile today", tone: "Thoughtful", reply: "Mira's eyes brighten. “The tiny bakery downstairs gave me the last strawberry tart. I saved half for tomorrow.”", points: 1 },
        { text: "Ask about her favorite constellation", tone: "Curious", reply: "“Cassiopeia,” she says, tracing its shape in the air. “It looks like a little crown.”", points: 1 },
        { text: "Tell her the room feels peaceful", tone: "Gentle", reply: "She relaxes into the pillow. “It does, doesn't it? I like how the rain makes everything slow down.”", points: 1 }
      ]
    },
    {
      question: "If you could go anywhere for one perfect day, where would you go?",
      mood: "her voice grows more animated",
      options: [
        { text: "A quiet seaside town", tone: "Dream together", reply: "“A little seaside town with a bookshop and no schedule,” she says. “We'd find the best place for hot chocolate.”", points: 1 },
        { text: "Ask what she would choose", tone: "Let her lead", reply: "“Somewhere new, but not too crowded. And I'd want good company more than a fancy view.” She smiles at you.", points: 1 },
        { text: "A stargazing trip in the hills", tone: "Make a plan", reply: "Her face lights up. “Blankets, thermoses, a sky full of stars. We should really do that sometime.”", points: 1 }
      ]
    },
    {
      question: "There's something I've been wanting to ask you…",
      mood: "a little bashful, but comfortable",
      options: [
        { text: "What helps you feel understood?", tone: "Listen closely", reply: "“When someone lets me finish, even if I'm taking the scenic route,” Mira says. “Thank you for asking.”", points: 1 },
        { text: "What are you proud of lately?", tone: "Encouraging", reply: "“I finally sent my illustrations to a little magazine. I was scared, but I did it.” Her smile turns quietly proud.", points: 1 },
        { text: "Is there anything on your mind?", tone: "Give her space", reply: "“Mostly good things tonight.” She pauses. “It feels nice to know I can talk when I need to.”", points: 1 }
      ]
    },
    {
      question: "I found an old photo earlier. It reminded me of a story…",
      mood: "happily lost in a memory",
      options: [
        { text: "Ask her to tell you the whole story", tone: "Be present", reply: "She tells you about a rainy train ride, a lost umbrella, and a stranger who shared their snacks. The story is better with every detail.", points: 1 },
        { text: "What did you learn from that day?", tone: "Reflect together", reply: "“That a small kindness can change the whole mood of a day,” she says. “I've tried to remember that.”", points: 1 },
        { text: "Share a favorite memory of yours", tone: "Trade stories", reply: "Mira listens with her chin in her hands. “I love that you told me that. I can picture it perfectly.”", points: 1 }
      ]
    },
    {
      question: "Do you ever wonder what the next year might bring?",
      mood: "thoughtful and quietly hopeful",
      options: [
        { text: "Ask what she hopes to make", tone: "Cheer her on", reply: "“A little illustrated book of ordinary, lovely things,” she says. “Maybe I can show you the first sketches soon.”", points: 1 },
        { text: "Tell her it's okay not to have it figured out", tone: "Reassure her", reply: "Mira gives a grateful nod. “I needed to hear that. We can take things one day at a time.”", points: 1 },
        { text: "Ask what would make tomorrow nice", tone: "Start small", reply: "“A slow breakfast, maybe a walk if the rain stops.” She grins. “And a message from you.”", points: 1 }
      ]
    },
    {
      question: "It's getting late. What should we remember about tonight?",
      mood: "warm, with a hint of goodbye",
      options: [
        { text: "That we can always make time to talk", tone: "A kind promise", reply: "“I like that promise,” she says softly. “Let's not wait so long before the next one.”", points: 1 },
        { text: "The strawberry tart and the stars", tone: "Keep the little things", reply: "“The best kind of evening is made of little things,” Mira says. “I'm glad we got to share them.”", points: 1 },
        { text: "Ask if she'd like another quiet evening soon", tone: "Make another plan", reply: "“I'd really like that.” She smiles and waves as you get ready to go. “Goodnight. Get home safe.”", points: 1 }
      ]
    }
  ];
  const storageKey = 'moonlit-letters-save-v1';
  const $ = (id) => document.getElementById(id);
  const dialogue = $('dialogue');
  const choices = $('choices');
  let state = load();
  let toastTimer;

  function freshState() { return { round: 0, affection: 0, selected: false, finished: false }; }
  function load() {
    try {
      const saved = JSON.parse(localStorage.getItem(storageKey));
      if (saved && Number.isInteger(saved.round) && saved.round >= 0 && saved.round <= rounds.length) {
        return { ...freshState(), ...saved, affection: Math.max(0, Math.min(6, saved.affection || 0)) };
      }
    } catch (_) { /* Ignore invalid or unavailable local storage. */ }
    return freshState();
  }
  function save() {
    try { localStorage.setItem(storageKey, JSON.stringify(state)); } catch (_) { /* Game remains playable without storage. */ }
  }
  function render() {
    const value = Math.min(state.affection, 6);
    $('affection-value').innerHTML = `${value} <small>/ 6</small>`;
    $('meter-fill').style.width = `${(value / 6) * 100}%`;
    $('affection-note').textContent = value >= 5 ? 'A bond built on listening' : value >= 3 ? 'The conversation feels easy' : value >= 1 ? 'A lovely evening is taking shape' : 'A lovely evening is just beginning';
    if (state.finished || state.round >= rounds.length) return renderEnding();
    const round = rounds[state.round];
    $('mood').textContent = round.mood;
    choices.innerHTML = '';
    if (state.selected) {
      const next = document.createElement('button');
      next.className = 'choice next-choice';
      next.type = 'button';
      next.innerHTML = `Continue the evening <span class="tone">Question ${state.round + 1} of ${rounds.length}</span><span class="arrow">→</span>`;
      next.addEventListener('click', nextRound);
      choices.append(next);
      return;
    }
    dialogue.textContent = round.question;
    round.options.forEach((option) => {
      const button = document.createElement('button');
      button.className = 'choice';
      button.type = 'button';
      button.innerHTML = `${escapeHTML(option.text)}<span class="tone">${escapeHTML(option.tone)}</span><span class="arrow">›</span>`;
      button.addEventListener('click', () => choose(option));
      choices.append(button);
    });
  }
  function choose(option) {
    state.affection = Math.min(6, state.affection + option.points);
    state.selected = true;
    dialogue.style.opacity = '0';
    window.setTimeout(() => { dialogue.textContent = option.reply; dialogue.style.opacity = '1'; }, 140);
    $('character').classList.add('happy');
    $('heart-pop').classList.remove('pop');
    void $('heart-pop').offsetWidth;
    $('heart-pop').classList.add('pop');
    save();
    render();
  }
  function nextRound() {
    state.round += 1;
    state.selected = false;
    if (state.round >= rounds.length) state.finished = true;
    save();
    render();
  }
  function renderEnding() {
    state.finished = true;
    const ending = state.affection >= 5
      ? { title: 'A promise beneath the moon', mood: 'close friends, with more stories ahead', text: 'The rain has softened to a whisper. Mira gives your hand a gentle squeeze before you go. “This was exactly the kind of evening I needed. Let's make more memories together.” A new little ritual begins.' }
      : state.affection >= 3
        ? { title: 'A lovely evening together', mood: 'comfortable and happy', text: 'At the door, Mira smiles warmly. “I'm glad we got to talk like this. Next time, you can tell me more about that story of yours.” The night ends with an easy promise to meet again.' }
        : { title: 'A quiet goodnight', mood: 'grateful for the company', text: 'Mira thanks you for spending part of your evening with her. There is no rush; trust takes time, and another conversation is always possible. You leave with a gentle goodnight.' };
    $('mood').textContent = ending.mood;
    dialogue.textContent = ending.text;
    choices.innerHTML = `<div class="ending-card"><span class="ending-kicker">YOUR EVENING WITH MIRA</span><strong>${ending.title}</strong><span>You listened, shared stories, and let the night unfold at its own pace.</span></div>`;
    const replay = document.createElement('button');
    replay.className = 'choice replay-choice';
    replay.type = 'button';
    replay.innerHTML = 'Begin a new evening <span class="arrow">↻</span>';
    replay.addEventListener('click', restart);
    choices.append(replay);
    save();
  }
  function restart() {
    state = freshState();
    save();
    $('character').classList.remove('happy');
    dialogue.style.opacity = '1';
    render();
    showToast('A new evening begins ✦');
  }
  function showToast(message) {
    const toast = $('toast');
    toast.textContent = message;
    toast.classList.add('show');
    window.clearTimeout(toastTimer);
    toastTimer = window.setTimeout(() => toast.classList.remove('show'), 1800);
  }
  function escapeHTML(value) {
    return value.replace(/[&<>"']/g, (char) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[char]);
  }
  $('restart').addEventListener('click', restart);
  $('sound-toggle').addEventListener('click', (event) => {
    const button = event.currentTarget;
    const active = button.classList.toggle('active');
    button.setAttribute('aria-pressed', String(active));
    showToast(active ? 'Imagine the soft sound of rain outside ☾' : 'Ambient sound off');
  });
  render();
})();

